package com.kai.automusic;
import android.app.*;import android.content.*;import android.media.*;import android.net.Uri;import android.os.*;import org.json.*;
public class PlayerService extends Service{MediaPlayer m;android.content.SharedPreferences p;int index=0,fail=0;boolean ready=false,want=false;String status="Waiting for charging";BroadcastReceiver power=new BroadcastReceiver(){public void onReceive(Context c,Intent i){if(!p.getBoolean("armed",false))return;if(Intent.ACTION_POWER_CONNECTED.equals(i.getAction())&&p.getBoolean("auto",true))play();else if(Intent.ACTION_POWER_DISCONNECTED.equals(i.getAction())&&p.getBoolean("unplug",true))pause();}};
 public void onCreate(){super.onCreate();p=getSharedPreferences("music",0);index=p.getInt("index",0);if(Build.VERSION.SDK_INT>=26)getSystemService(NotificationManager.class).createNotificationChannel(new NotificationChannel("music","Auto Music",NotificationManager.IMPORTANCE_LOW));IntentFilter f=new IntentFilter();f.addAction(Intent.ACTION_POWER_CONNECTED);f.addAction(Intent.ACTION_POWER_DISCONNECTED);registerReceiver(power,f);}
 Notification notification(){Notification.Builder b=Build.VERSION.SDK_INT>=26?new Notification.Builder(this,"music"):new Notification.Builder(this);return b.setSmallIcon(android.R.drawable.ic_media_play).setContentTitle("Kai Auto Music").setContentText(status).setOngoing(true).setContentIntent(PendingIntent.getActivity(this,0,new Intent(this,MainActivity.class),PendingIntent.FLAG_IMMUTABLE)).build();}void update(String s){status=s;getSystemService(NotificationManager.class).notify(1,notification());}
 public int onStartCommand(Intent i,int flags,int id){startForeground(1,notification());String a=i==null?"ARM":i.getAction();if("ARM".equals(a)){p.edit().putBoolean("armed",true).apply();Intent battery=registerReceiver(null,new IntentFilter(Intent.ACTION_BATTERY_CHANGED));if(battery!=null&&battery.getIntExtra("plugged",0)!=0&&p.getBoolean("auto",true))play();}else if("PLAY".equals(a))play();else if("PAUSE".equals(a))pause();else if("NEXT".equals(a)){fail=0;advance(true);}return START_STICKY;}
 JSONArray songs(){try{return new JSONArray(p.getString("songs","[]"));}catch(Exception e){return new JSONArray();}}void play(){want=true;fail=0;if(m!=null){if(ready){m.start();update("Playing track "+(index+1));}return;}load();}void pause(){want=false;if(m!=null&&ready&&m.isPlaying())m.pause();update("Paused");}void release(){if(m!=null){m.release();m=null;}ready=false;}
 void load(){release();JSONArray a=songs();if(a.length()==0){update("Playlist empty");return;}index=Math.max(0,Math.min(index,a.length()-1));p.edit().putInt("index",index).apply();try{m=new MediaPlayer();m.setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_MUSIC).build());m.setWakeMode(this,PowerManager.PARTIAL_WAKE_LOCK);m.setDataSource(this,Uri.parse(a.getString(index)));m.setOnPreparedListener(x->{ready=true;fail=0;if(want){x.start();update("Playing track "+(index+1));}});m.setOnCompletionListener(x->advance(false));m.setOnErrorListener((x,w,e)->{skipError();return true;});m.prepareAsync();}catch(Exception e){skipError();}}
 void skipError(){release();if(++fail>=songs().length()){want=false;update("No playable files");return;}index=(index+1)%songs().length();new Handler(Looper.getMainLooper()).post(()->{if(want)load();});}void advance(boolean manual){int n=songs().length();if(n==0){release();return;}if(manual)want=true;if(!manual&&!want)return;if(p.getBoolean("shuffle",false)&&n>1)index=(index+1+new java.util.Random().nextInt(n-1))%n;else if(index+1>=n&&!manual&&!p.getBoolean("repeat",true)){release();want=false;index=0;update("Playlist finished");return;}else index=(index+1)%n;load();}public IBinder onBind(Intent i){return null;}public void onDestroy(){unregisterReceiver(power);release();super.onDestroy();}}